package cn.linkdeck.qa;
import android.app.*;import android.content.*;import android.os.*;import cn.linkdeck.adb.*;import java.io.*;import java.lang.reflect.*;
/** Actual transport, PackageManager proof and preserving update/downgrade in a disposable emulator. */
public class Version010SystemChecks extends DesktopSystemChecks {
 File asset(String name)throws Exception{File f=new File(getTargetContext().getExternalFilesDir(null),name);try(InputStream in=getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 Object proofField(Object proof,String name)throws Exception{Field f=proof.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(proof);}
 public void onStart(){Bundle result=new Bundle();boolean successful=false;AdbClient client=null;boolean owned=false;try{
  if(!shell("getprop ro.kernel.qemu").trim().equals("1"))throw new IOException("Disposable emulator only");
  if(shell("pm path app.orchard.tv").startsWith("package:"))throw new IOException("Clean emulator required; existing installation will not be replaced");
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("resume_connection",false).commit();activity=startActivitySync(new Intent().setClassName("cn.linkdeck.adb","cn.linkdeck.adb.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
  File old=asset("desktop-fixture.apk"),newer=asset("desktop-newer.apk");shell("cp "+old+" /data/local/tmp/qa010-base.apk");check(shell("pm install -r /data/local/tmp/qa010-base.apk").contains("Success"),"isolated version 900 fixture installed");owned=true;
  File identityDir=new File(getTargetContext().getCacheDir(),"qa010-identity-"+java.util.UUID.randomUUID());AdbIdentity identity=new AdbIdentity(identityDir);new AdbIdentity(identityDir);check(true,"Android-generated authentication key pair round-trips through private storage");client=new AdbClient();client.connect("127.0.0.1",5555,identity);final AdbClient adb=client;
  Method method=activity.getClass().getDeclaredMethod("installedProof",AdbClient.class,String.class);method.setAccessible(true);Object proof=method.invoke(activity,client,AerialSupport.FULL);
  check(((Long)proofField(proof,"code"))==900L&&proofField(proof,"sha").equals(AerialDownload.sha256(old)),"actual ADB pull and Android package parser prove installed code and exact APK digest");
  Method archive=activity.getClass().getDeclaredMethod("archiveInfo",File.class);archive.setAccessible(true);Object pi=archive.invoke(activity,newer);Method sign=activity.getClass().getDeclaredMethod("signerSet",android.content.pm.PackageInfo.class);sign.setAccessible(true);String cert=(String)sign.invoke(activity,pi);AerialSafety.sameSigners((String)proofField(proof,"signers"),cert);check(true,"actual existing and update APK signer sets match");
  File official=asset("aerial-standard.apk");Object officialInfo=archive.invoke(activity,official);String officialCert=(String)sign.invoke(activity,officialInfo);boolean rejected=false;try{AerialSafety.sameSigners(cert,officialCert);}catch(IOException expected){rejected=true;}check(rejected,"actual upstream certificate is rejected against unrelated fixture signer");
  shell("mkdir -p /sdcard/Android/data/app.orchard.tv/files; echo KEEP_010 > /sdcard/Android/data/app.orchard.tv/files/qa010-marker");
  ApkTransfer.Device d=new ApkTransfer.Device(){public String shell(String c)throws Exception{return adb.shell(c).require();}public void push(File f,String remote)throws Exception{try(InputStream in=new FileInputStream(f)){adb.push(in,remote,null);}}};
  DesktopAssistant.Snapshot snapshot=DesktopAssistant.inspect(c->adb.shell(c).require(),"127.0.0.1:5555");
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putString("port","5555").commit();set("adb",adb);set("host","127.0.0.1");
  AerialInstaller.Installed before=AerialInstaller.read(d,AerialSupport.FULL);AerialInstaller.install(newer,AerialSupport.FULL,901,before,d);check(AerialInstaller.read(d,AerialSupport.FULL).code==901,"actual preserving update reads back version 901");
  boolean implicit=false;try{AerialInstaller.install(old,AerialSupport.FULL,900,AerialInstaller.read(d,AerialSupport.FULL),d);}catch(IOException expected){implicit=true;}check(implicit&&AerialInstaller.read(d,AerialSupport.FULL).code==901,"implicit downgrade remains blocked before transfer");
  String outcome;try{AerialInstaller.install(old,AerialSupport.FULL,900,AerialInstaller.read(d,AerialSupport.FULL),d,true);check(AerialInstaller.read(d,AerialSupport.FULL).code==900,"system accepted explicit -r -d and installed code was verified");outcome="accepted";}catch(AerialInstaller.RollbackFailure expected){check(AerialInstaller.read(d,AerialSupport.FULL).code==901,"system refused explicit downgrade and newer installation remains");outcome="refused";}
  check(shell("cat /sdcard/Android/data/app.orchard.tv/files/qa010-marker").trim().equals("KEEP_010"),"update and rollback attempt preserve external data marker");
  check(shell("find /data/local/tmp -maxdepth 1 -name 'linkdeck_phone_*.apk'").trim().isEmpty(),"remote transfer temporary files cleaned up");
  result.putString("stream","VERSION 010 REAL SYSTEM PASSED: "+passes+" checks; rollback "+outcome+". External marker only; private data compatibility not asserted.\n");successful=true;
 }catch(Throwable t){result.putString("stream",android.util.Log.getStackTraceString(t));}finally{if(client!=null)client.close();try{if(owned){shell("pm uninstall app.orchard.tv");shell("rm -f /data/local/tmp/qa010-base.apk");}}catch(Exception ignored){}}finish(successful?-1:0,result);}
}
